from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PowerMeter(SchemaObject):
    available_measurements = SchemaField(name='availableMeasurements')

    def __init__(self, available_measurements):
        self.available_measurements = available_measurements

        super(PowerMeter, self).__init__()


class RmodId(SchemaObject):
    configuration = SchemaField(name='configuration', optional=True)
    runtime = SchemaField(name='runtime')

    def __init__(self, configuration, runtime):
        self.configuration = configuration
        self.runtime = runtime

        super(RmodId, self).__init__()


class Rmods(SchemaObject):
    rmod_id = SchemaField(name='id', klass=RmodId)
    product_name = SchemaField(name='productName', optional=True)
    power_meter = SchemaField(name='powerMeter', klass=PowerMeter, optional=True)
    is_fan_measurement_supported = SchemaField(name='isFanMeasurementSupported', optional=True)
    fans = SchemaField(name='fans', optional=True)

    def __init__(self, rmod_id, product_name, power_meter, is_fan_measurement_supported, fans):
        self.rmod_id = rmod_id
        self.product_name = product_name
        self.power_meter = power_meter
        self.is_fan_measurement_supported = is_fan_measurement_supported
        self.fans = fans

        super(Rmods, self).__init__()


class RealTimeMeasurementsInfo(SchemaObject):
    act_power_meter = SchemaField(name='actPowerMeter')
    rmods = SchemaField(name="rmods", klass=Rmods, many=True)

    def __init__(self, act_power_meter, rmods):
        self.act_power_meter = act_power_meter
        self.rmods = rmods

        super(RealTimeMeasurementsInfo, self).__init__()
